<template><div class="page"><div class="page-head"><div><h2>施工巡检配置</h2><p>分别维护安保、工程、保洁扫码巡检时需要填写的检查项。</p></div><el-button type="primary" :loading="saving" @click="save">保存当前题库</el-button></div>
<el-tabs v-model="active" @tab-change="loadCurrent"><el-tab-pane v-for="type in types" :key="type.value" :name="type.value" :label="type.label"/></el-tabs>
<el-card shadow="never"><el-form label-position="top"><el-row :gutter="16"><el-col :xs="24" :sm="16"><el-form-item label="题库名称"><el-input v-model="current.name" maxlength="100"/></el-form-item></el-col><el-col :xs="24" :sm="8"><el-form-item label="状态"><el-switch v-model="current.enabled" active-text="启用" inactive-text="停用"/></el-form-item></el-col></el-row></el-form>
<div class="toolbar"><strong>检查题（{{ current.fields.length }}）</strong><el-button type="primary" plain @click="addField">增加检查题</el-button></div>
<el-empty v-if="!current.fields.length" description="暂无检查题"/>
<div v-for="(field,index) in current.fields" :key="field.key" class="question"><div class="question-title"><b>{{ index+1 }}. {{ field.label||'未命名检查题' }}</b><div><el-button link :disabled="index===0" @click="move(index,-1)">上移</el-button><el-button link :disabled="index===current.fields.length-1" @click="move(index,1)">下移</el-button><el-button link type="danger" @click="remove(index)">删除</el-button></div></div>
<el-row :gutter="12"><el-col :xs="24" :md="12"><el-form-item label="检查题"><el-input v-model="field.label" maxlength="100"/></el-form-item></el-col><el-col :xs="24" :md="6"><el-form-item label="填写方式"><el-select v-model="field.controlType" style="width:100%" @change="typeChanged(field)"><el-option v-for="c in controls" :key="c.value" :label="c.label" :value="c.value"/></el-select></el-form-item></el-col><el-col :xs="24" :md="6"><el-form-item label="设置"><el-checkbox v-model="field.required">必填</el-checkbox><el-checkbox v-model="field.enabled">启用</el-checkbox></el-form-item></el-col></el-row>
<el-row :gutter="12"><el-col v-if="['SELECT','MULTISELECT'].includes(field.controlType)" :xs="24" :md="12"><el-form-item label="选项（每行一项）"><el-input v-model="field.optionText" type="textarea" :rows="3"/></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="正常值（留空表示不自动判异常）"><template v-if="field.controlType==='NORMAL_ABNORMAL'"><el-radio-group v-model="field.normalValue"><el-radio value="NORMAL">正常</el-radio><el-radio value="ABNORMAL">异常</el-radio></el-radio-group></template><template v-else-if="field.controlType==='BOOLEAN'"><el-radio-group v-model="field.normalValue"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group></template><el-input v-else v-model="field.normalValue" placeholder="与填写值不一致时判为异常"/></el-form-item></el-col></el-row>
<el-checkbox v-model="field.requirePhotoOnAbnormal">该项异常时必须上传现场照片</el-checkbox></div>
</el-card></div></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { constructionInspectionTemplateApi, type ConstructionInspectionField, type ConstructionInspectionTemplate } from '@/api/construction'
type EditorField=ConstructionInspectionField&{optionText?:string}
const types=[{value:'SECURITY',label:'安保巡检'},{value:'ENGINEERING',label:'工程巡检'},{value:'CLEANING',label:'保洁巡检'}]
const controls=[{value:'NORMAL_ABNORMAL',label:'正常/异常'},{value:'BOOLEAN',label:'是/否'},{value:'SELECT',label:'单选'},{value:'MULTISELECT',label:'多选'},{value:'NUMBER',label:'数字'},{value:'TEXT',label:'文字'}]
const active=ref('SECURITY'),saving=ref(false),templates=ref<ConstructionInspectionTemplate[]>([])
const current=reactive<{name:string;enabled:boolean;fields:EditorField[]}>({name:'',enabled:true,fields:[]})
function parseFields(raw:string):EditorField[]{try{return (JSON.parse(raw)||[]).map((f:any)=>({...f,enabled:f.enabled!==false,optionText:(f.options||[]).join('\n')}))}catch{return[]}}
function loadCurrent(){const t=templates.value.find(i=>i.inspectionType===active.value);current.name=t?.name||types.find(i=>i.value===active.value)?.label||'';current.enabled=t?.enabled===true||Number(t?.enabled)===1;current.fields=parseFields(t?.fieldsJson||'[]')}
function addField(){current.fields.push({key:`question_${Date.now()}`,label:'',controlType:'NORMAL_ABNORMAL',required:true,normalValue:'NORMAL',requirePhotoOnAbnormal:true,enabled:true,sortOrder:(current.fields.length+1)*10})}
function typeChanged(f:EditorField){if(f.controlType==='NORMAL_ABNORMAL')f.normalValue='NORMAL';else if(f.controlType==='BOOLEAN')f.normalValue=true;else f.normalValue=''}
function move(i:number,d:number){const j=i+d;[current.fields[i],current.fields[j]]=[current.fields[j],current.fields[i]]}
async function remove(i:number){await ElMessageBox.confirm('确认删除这道检查题？','提示',{type:'warning'});current.fields.splice(i,1)}
async function save(){if(!current.name.trim()){ElMessage.warning('请填写题库名称');return}if(!current.fields.length){ElMessage.warning('至少保留一道检查题');return}if(current.fields.some(f=>!f.label.trim())){ElMessage.warning('请填写所有检查题名称');return}const fields=current.fields.map((f,i)=>{const x:any={...f,sortOrder:(i+1)*10};x.options=(f.optionText||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean);delete x.optionText;return x});saving.value=true;try{const saved=await constructionInspectionTemplateApi.save(active.value,{name:current.name.trim(),enabled:current.enabled,fieldsJson:JSON.stringify(fields)}) as any;const idx=templates.value.findIndex(i=>i.inspectionType===active.value);if(idx>=0)templates.value[idx]=saved;ElMessage.success('施工巡检题库已保存')}finally{saving.value=false}}
onMounted(async()=>{templates.value=await constructionInspectionTemplateApi.list(false) as any;loadCurrent()})
</script>
<style scoped>.page{padding:20px}.page-head,.toolbar,.question-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-head h2{margin:0 0 6px}.page-head p{margin:0;color:#909399}.toolbar{margin-bottom:14px}.question{border:1px solid #e4e7ed;border-radius:8px;padding:16px;margin-top:12px;background:#fafafa}.question-title{margin-bottom:12px}@media(max-width:768px){.page{padding:12px}.page-head{align-items:flex-start}.question{padding:12px}.question-title{align-items:flex-start}}</style>
